import assert from 'node:assert/strict'
import { readFileSync, writeFileSync } from 'node:fs'
import { createHash } from 'node:crypto'
import vm from 'node:vm'
import ts from '../app/node_modules/typescript/lib/typescript.js'
const sourcePath = 'curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_INFORMATIK.de.json'
const sha = (value: Buffer | string) => createHash('sha256').update(value).digest('hex')
const sourceBytes = readFileSync(sourcePath)
assert.equal(sha(sourceBytes), '93a653b110949ff410a73bd750b2a605a9ab0329fe1cd157f016869d848e1f7e')
const source = JSON.parse(sourceBytes.toString('utf8'))
const implementation = 'app/scripts/generateCurriculumQualityStatus.ts'
const code = readFileSync(implementation, 'utf8')
const names = ['normalizeExamTextForInspection', 'hasExamSubtaskMarkers', 'hasScoringStructure', 'hasBlockingExamReviewStatus', 'isPlaceholderExamData', 'concreteExamReadinessIssues', 'stringArray', 'examReleaseCoverageIssues']
const functions = names.map(name => {
  const start = code.indexOf('function ' + name + '(')
  assert(start >= 0)
  const end = code.indexOf('\n}\n', start)
  assert(end > start)
  return code.slice(start, end + 2)
}).join('\n')
const context: any = {}
vm.runInNewContext(ts.transpileModule(functions + '\nthis.checks = {' + names.join(',') + '};', {
  compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.None },
}).outputText, context)
const goals = source.goals.filter((goal: any) => goal.extendedData?.routeTerminal && goal.examData)
assert.equal(goals.length, 6)
const rows = goals.map((goal: any) => ({
  goalId: goal.id,
  title: goal.title,
  examDataPresent: true,
  concreteReadinessIssues: Array.from(context.checks.concreteExamReadinessIssues(goal)),
  releaseCoverageIssues: Array.from(context.checks.examReleaseCoverageIssues(goal)),
  detectedAsPlaceholderByExistingCode: context.checks.isPlaceholderExamData(goal),
  recognizedSubtaskMarkers: context.checks.hasExamSubtaskMarkers(context.checks.normalizeExamTextForInspection(goal.examData.taskContent)),
  scoringStructureAccepted: context.checks.hasScoringStructure(goal),
}))
assert(rows.every((row: any) => row.concreteReadinessIssues.length === 0 && row.releaseCoverageIssues.length === 0))
const result = {
  status: 'OBSERVED-native-CQR201-202-203-shape-acceptance-is-not-content-approval',
  source: { path: sourcePath, rawSha256: sha(sourceBytes) },
  implementation: { path: implementation, rawSha256: sha(code) },
  method: 'Execute exact extracted current native pure helpers; no full central generator, no validator edit, no source mutation.',
  rows,
}
writeFileSync('tmp/informatics-terminal-native-checks.json', JSON.stringify(result, null, 2) + '\n')
console.log(JSON.stringify(result))
